static const char water_vs[]="#version 300 es\nprecision highp float;\nlayout(location=0)in vec3 position;layout(location=1)in vec2 uv;layout(location=2)in vec3 n;layout(location=3)in vec3 t;layout(location=4)in vec3 b;layout(location=5)in vec4 color;\nuniform mat4 vp;uniform vec4 m[6];uniform float time;\nout vec3 W,N,T,B;out vec4 C,clip;out vec2 U0,U1,U2,U3;\nvoid oaRiverUV(vec2 uv,float time,vec4 m[6],out vec2 baseUV,out vec2 foamUV,out vec2 detailUV,out vec2 refractionUV) {\n    baseUV=uv+time*vec2(m[0].w,m[1].x)*m[0].x;\n    vec2 scrollingFoamUV=uv+vec2(time*m[1].y,0.0);\n    foamUV=scrollingFoamUV*m[0].z;\n    detailUV=scrollingFoamUV*m[0].y;\n    refractionUV=uv+time*m[1].zw;\n}\nvoid main(){vec4 q=vp*vec4(position,1.0);gl_Position=q;clip=vec4(q.xy,.5*(q.z+q.w),q.w);W=position;N=n;T=t;B=b;C=color;oaRiverUV(uv,time,m,U0,U1,U2,U3);}\n";
static const char water_fs[]="#version 300 es\nprecision highp float;precision highp sampler2D;precision highp samplerCube;\nin vec3 W,N,T,B;in vec4 C,clip;in vec2 U0,U1,U2,U3;\nuniform sampler2D baseMap,normalMap,foamMap,detailMap,refractionMap,sceneColor,sceneDepth;\nuniform samplerCube probeCube,ambientCube;uniform vec4 m[6],lightData[8],globalTint,lumFactors;uniform vec3 eye,sunDirection,sunColor,shadowColor,waterFog,lumTint;uniform vec2 invDepth;uniform bool pointLights;out vec4 outputColor;\n// Reviewed translation of shipped 3316e4b0586bb12a pixel family.\n// Active capture PS946 (no local point lights) and PS956 (four local lights).\n// Requires native vertex UV, tangent frame, vertex red, and ORIGINAL D3D clip.\n// Scene textures must be a stable PRE-WATER copy; never sample active framebuffer.\n// m[6] is native96 from decoded-materials.json; m[2].w is ignored padding.\n// Coordinate convention: world z up; native reflection probe is sampled in xzy.\nvec2 oaSceneUV(vec2 uv,bool lowerLeft){return lowerLeft?vec2(uv.x,1.0-uv.y):uv;}\nvec3 oaDecodeRiverNormal(vec4 s) {\n    vec2 xz=vec2(s.r*s.a,s.g)*2.0-1.0;\n    return vec3(xz.x,sqrt(clamp(1.0-dot(xz,xz),0.0,1.0)),xz.y);\n}\nvec3 oaDecodeRefraction(vec4 s) {\n    return vec3(vec2(s.r*s.a,s.g)*2.0-1.0,0.0);\n}\n// Execute in VERTEX stage, then interpolate these UVs (all affine per vertex).\nvoid oaRiverUV(vec2 uv,float time,vec4 m[6],out vec2 baseUV,out vec2 foamUV,out vec2 detailUV,out vec2 refractionUV) {\n    baseUV=uv+time*vec2(m[0].w,m[1].x)*m[0].x;\n    vec2 scrollingFoamUV=uv+vec2(time*m[1].y,0.0);\n    foamUV=scrollingFoamUV*m[0].z;\n    detailUV=scrollingFoamUV*m[0].y;\n    refractionUV=uv+time*m[1].zw;\n}\nvec4 oaNativeRiver(\n    sampler2D baseMap,sampler2D normalMap,sampler2D foamMap,\n    sampler2D detailNormalMap,sampler2D refractionMap,\n    sampler2D sceneColor,sampler2D sceneDepth,\n    samplerCube environmentProbe,samplerCube ambientCube,\n    vec4 m[6],vec2 uvBase,vec2 uvFoam,vec2 uvDetail,vec2 uvRefraction,\n    vec3 worldPosition,vec3 eye,vec3 normal,vec3 tangent,vec3 binormal,\n    float vertexRed,vec4 nativeClip,vec2 invDepthTransform,\n    vec3 sunDirection,vec3 sunColor,vec3 shadowColor,\n    vec3 waterFogGlobals,vec4 lightData[8],bool pointLights,bool sceneTextureLowerLeft,\n    vec4 globalTint,vec4 luminanceFactors,vec3 luminanceTint) {\n    vec3 V=normalize(eye-worldPosition);\n    vec3 n1=oaDecodeRiverNormal(texture(normalMap,uvBase));\n    vec3 n2=oaDecodeRiverNormal(texture(detailNormalMap,uvDetail));\n    vec3 nr=normalize((n1+n2)*vec3(.5,2.0,.5));\n    vec3 N=normalize(nr.y*normal+nr.x*tangent+nr.z*binormal);\n    vec3 env=texture(environmentProbe,reflect(-V.xzy,nr)).rgb;\n    vec3 base=mix(texture(baseMap,uvBase).rgb,env,m[2].x);\n    vec2 screenUV=clamp(nativeClip.xy/nativeClip.w*vec2(.5,-.5)+.5,0.0,1.0);\n    // Flip each final native-coordinate sample only; this also flips refraction Y correctly.\n    float originalDepth=1.0/(invDepthTransform.x*texture(sceneDepth,oaSceneUV(screenUV,sceneTextureLowerLeft)).r+invDepthTransform.y);\n    float originalDifference=originalDepth-nativeClip.z;\n    vec3 originalColor=texture(sceneColor,oaSceneUV(screenUV,sceneTextureLowerLeft)).rgb;\n    vec2 refractedUV=screenUV+oaDecodeRefraction(texture(refractionMap,uvRefraction)).xy*m[2].y;\n    float refractedDepth=1.0/(invDepthTransform.x*texture(sceneDepth,oaSceneUV(refractedUV,sceneTextureLowerLeft)).r+invDepthTransform.y);\n    bool valid=nativeClip.z<refractedDepth;\n    float difference=(valid?refractedDepth:originalDepth)-nativeClip.z;\n    vec3 color=valid?texture(sceneColor,oaSceneUV(refractedUV,sceneTextureLowerLeft)).rgb:originalColor;\n    // Native pow receives difference; valid draw/visible-depth path is positive.\n    float tintAmount=clamp(pow(difference,1.5)*m[2].z,0.0,1.0);\n    color=mix(color,m[3].rgb,tintAmount);\n    float depthFog=1.0-exp(-difference*m[2].z*waterFogGlobals.x);\n    color+=waterFogGlobals.z*depthFog*(m[3].rgb*.4-color);\n    float fresnel=clamp(clamp(dot(N,V)+m[5].z,0.0,1.0),.3,.8);\n    vec3 combined=mix(base,color,fresnel);\n    combined+=waterFogGlobals.z*((base*(1.0-fresnel)+color)-combined);\n    float opacityScale=.01+waterFogGlobals.z*(waterFogGlobals.y-.01);\n    float a=originalDifference*opacityScale;\n    float alpha=clamp(a*a*a,0.0,1.0);\n    combined=mix(texture(foamMap,uvFoam).rgb,combined,vertexRed);\n    vec3 R=reflect(-V,N);\n    vec3 diffuseLights=vec3(0.0),specularLights=vec3(0.0);\n    float exponent=m[5].y*.25;\n    if(pointLights)for(int i=0;i<4;i++){\n        vec3 delta=lightData[i*2].xyz-worldPosition;float dist=length(delta);vec3 L=delta/dist;\n        float atten=clamp(dist*lightData[i*2].w+lightData[i*2+1].w,0.0,1.0)*clamp(dot(N,L),0.0,1.0);\n        diffuseLights+=lightData[i*2+1].rgb*atten;\n        specularLights+=lightData[i*2+1].rgb*(atten*pow(max(clamp(dot(L,R),0.0,1.0),.00001),exponent));\n    }\n    float nl=clamp(dot(N,sunDirection),0.0,1.0);\n    vec3 diffuse=sunColor*nl+diffuseLights+texture(ambientCube,N.xzy).rgb+(1.0-nl)*shadowColor;\n    vec3 spec=sunColor*(nl*pow(max(clamp(dot(sunDirection,R),0.0,1.0),.00001),exponent))+specularLights;\n    vec4 result=vec4(combined*diffuse+spec*m[5].x,alpha)*globalTint;\n    float lum=dot(result.rgb,luminanceFactors.rgb);\n    result.rgb+=luminanceFactors.w*(lum*luminanceTint-result.rgb);\n    return result;\n}\nvoid main(){outputColor=oaNativeRiver(baseMap,normalMap,foamMap,detailMap,refractionMap,sceneColor,sceneDepth,probeCube,ambientCube,m,U0,U1,U2,U3,W,eye,N,T,B,C.r,clip,invDepth,sunDirection,sunColor,shadowColor,waterFog,lightData,pointLights,true,globalTint,lumFactors,lumTint);}\n";
typedef struct {unsigned w,h,bytes;const unsigned char *pixels;} mip;
typedef struct {unsigned id,faces,w,h,levels;mip level[16];GLuint gpu;} tex;
typedef struct {unsigned id,material,probe,nv,ni,points,texid[5];const float *m,*lights,*tint,*lum,*lumtint,*vertices;const uint32_t *indices;float bounds[6];GLuint vao,vbo,ibo;} mesh;
typedef struct {unsigned char*data;size_t size;unsigned nt,nm;tex *t;mesh *m;GLuint program;} state;
static int take(state*s,size_t*o,size_t n,const unsigned char**p){if(n>s->size-*o)return 0;*p=s->data+*o;*o+=n;return 1;}
static uint32_t u32(const unsigned char*p){uint32_t n;memcpy(&n,p,4);return n;}
static tex*findtex(state*s,unsigned id){unsigned i;for(i=0;i<s->nt;i++)if(s->t[i].id==id)return s->t+i;return NULL;}
void oa_native_water_gpu_close(oa_native_water*w){state*s=(state*)w->state;unsigned i;if(!s)return;for(i=0;s->t&&i<s->nt;i++){if(s->t[i].gpu)glDeleteTextures(1,&s->t[i].gpu);s->t[i].gpu=0;}for(i=0;s->m&&i<s->nm;i++){mesh*m=s->m+i;if(m->vao)glDeleteVertexArrays(1,&m->vao);if(m->vbo)glDeleteBuffers(1,&m->vbo);if(m->ibo)glDeleteBuffers(1,&m->ibo);m->vao=m->vbo=m->ibo=0;}if(s->program)glDeleteProgram(s->program);s->program=0;}
void oa_native_water_close(oa_native_water*w){state*s=(state*)w->state;if(!s)return;oa_native_water_gpu_close(w);free(s->data);free(s->t);free(s->m);free(s);w->state=NULL;}
int oa_native_water_open(oa_native_water*w,AAssetManager*am,const char*path){AAsset*a;state*s;size_t o=0;const unsigned char*p;unsigned i,j;if(w->state)return 1;a=AAssetManager_open(am,path,AASSET_MODE_BUFFER);if(!a)return 0;s=(state*)calloc(1,sizeof(*s));if(!s){AAsset_close(a);return 0;}w->state=s;s->size=(size_t)AAsset_getLength(a);s->data=(unsigned char*)malloc(s->size);if(!s->data||AAsset_read(a,s->data,s->size)!=(int)s->size){AAsset_close(a);goto bad;}AAsset_close(a);
 if(!take(s,&o,16,&p)||memcmp(p,"OAWP",4)||u32(p+4)!=2)goto bad;s->nt=u32(p+8);s->nm=u32(p+12);if(s->nt>64||s->nm>128)goto bad;s->t=(tex*)calloc(s->nt,sizeof(tex));s->m=(mesh*)calloc(s->nm,sizeof(mesh));if(!s->t||!s->m)goto bad;
 for(i=0;i<s->nt;i++){tex*t=s->t+i;unsigned total,seen=0,k;if(!take(s,&o,24,&p))goto bad;t->id=u32(p);t->faces=u32(p+4);t->w=u32(p+8);t->h=u32(p+12);t->levels=u32(p+16);total=u32(p+20);if((t->faces!=1&&t->faces!=6)||!t->w||!t->h||t->w>8192||t->h>8192||!t->levels||t->levels>16)goto bad;
  for(k=0;k<t->levels;k++){mip*l=t->level+k;unsigned expectedw=t->w>>k,expectedh=t->h>>k;if(!expectedw)expectedw=1;if(!expectedh)expectedh=1;if(!take(s,&o,12,&p))goto bad;l->w=u32(p);l->h=u32(p+4);l->bytes=u32(p+8);if(l->w!=expectedw||l->h!=expectedh||l->bytes!=(size_t)l->w*l->h*t->faces*4||!take(s,&o,l->bytes,&p))goto bad;l->pixels=p;if(seen>UINT32_MAX-l->bytes)goto bad;seen+=l->bytes;}if(seen!=total)goto bad;}

 for(i=0;i<s->nm;i++){mesh*m=s->m+i;if(!take(s,&o,24,&p))goto bad;m->id=u32(p);m->material=u32(p+4);m->probe=u32(p+8);m->nv=u32(p+12);m->ni=u32(p+16);m->points=u32(p+20);if(m->nv>1000000||m->ni>3000000)goto bad;
 #define FIELD(F,N) if(!take(s,&o,(N)*4,&p))goto bad;m->F=(const float*)p
 FIELD(m,24);FIELD(lights,32);FIELD(tint,4);FIELD(lum,4);FIELD(lumtint,3);
 #undef FIELD
 if(!take(s,&o,20,&p))goto bad;for(j=0;j<5;j++){m->texid[j]=u32(p+j*4);if(!findtex(s,m->texid[j]))goto bad;}if(!findtex(s,m->probe))goto bad;
 if(!take(s,&o,(size_t)m->nv*72,&p))goto bad;m->vertices=(const float*)p;if(!take(s,&o,(size_t)m->ni*4,&p))goto bad;m->indices=(const uint32_t*)p;for(j=0;j<m->ni;j++)if(m->indices[j]>=m->nv)goto bad;
 for(j=0;j<3;j++){unsigned k;m->bounds[j]=1e30f;m->bounds[j+3]=-1e30f;for(k=0;k<m->nv;k++){float v=m->vertices[k*18+j];if(!isfinite(v))goto bad;if(v<m->bounds[j])m->bounds[j]=v;if(v>m->bounds[j+3])m->bounds[j+3]=v;}}}
 if(o!=s->size)goto bad;return 1;
 bad:oa_native_water_close(w);return 0;
}
static GLuint shader(GLenum type,const char*source){GLuint s=glCreateShader(type);GLint ok;glShaderSource(s,1,&source,NULL);glCompileShader(s);glGetShaderiv(s,GL_COMPILE_STATUS,&ok);if(!ok){glDeleteShader(s);return 0;}return s;}
static int gpu(state*s){unsigned i,j;GLuint v,f;GLint ok;if(s->program)return 1;v=shader(GL_VERTEX_SHADER,water_vs);f=shader(GL_FRAGMENT_SHADER,water_fs);if(!v||!f){if(v)glDeleteShader(v);if(f)glDeleteShader(f);return 0;}s->program=glCreateProgram();glAttachShader(s->program,v);glAttachShader(s->program,f);glLinkProgram(s->program);glDeleteShader(v);glDeleteShader(f);glGetProgramiv(s->program,GL_LINK_STATUS,&ok);if(!ok)return 0;
 for(i=0;i<s->nt;i++){tex*t=s->t+i;unsigned k;GLenum target=t->faces==6?GL_TEXTURE_CUBE_MAP:GL_TEXTURE_2D;glGenTextures(1,&t->gpu);glBindTexture(target,t->gpu);for(k=0;k<t->levels;k++){mip*l=t->level+k;for(j=0;j<t->faces;j++)glTexImage2D(t->faces==6?GL_TEXTURE_CUBE_MAP_POSITIVE_X+j:GL_TEXTURE_2D,k,GL_RGBA8,l->w,l->h,0,GL_RGBA,GL_UNSIGNED_BYTE,l->pixels+(size_t)j*l->w*l->h*4);}glTexParameteri(target,GL_TEXTURE_BASE_LEVEL,0);glTexParameteri(target,GL_TEXTURE_MAX_LEVEL,t->levels-1);glTexParameteri(target,GL_TEXTURE_MIN_FILTER,GL_LINEAR_MIPMAP_LINEAR);glTexParameteri(target,GL_TEXTURE_MAG_FILTER,GL_LINEAR);glTexParameteri(target,GL_TEXTURE_WRAP_S,t->faces==6?GL_CLAMP_TO_EDGE:GL_REPEAT);glTexParameteri(target,GL_TEXTURE_WRAP_T,t->faces==6?GL_CLAMP_TO_EDGE:GL_REPEAT);if(t->faces==6)glTexParameteri(target,GL_TEXTURE_WRAP_R,GL_CLAMP_TO_EDGE);}

 for(i=0;i<s->nm;i++){mesh*m=s->m+i;const unsigned sizes[7]={3,2,3,3,3,4,0};const unsigned offsets[6]={0,12,20,32,44,56};glGenVertexArrays(1,&m->vao);glBindVertexArray(m->vao);glGenBuffers(1,&m->vbo);glBindBuffer(GL_ARRAY_BUFFER,m->vbo);glBufferData(GL_ARRAY_BUFFER,(GLsizeiptr)m->nv*72,m->vertices,GL_STATIC_DRAW);glGenBuffers(1,&m->ibo);glBindBuffer(GL_ELEMENT_ARRAY_BUFFER,m->ibo);glBufferData(GL_ELEMENT_ARRAY_BUFFER,(GLsizeiptr)m->ni*4,m->indices,GL_STATIC_DRAW);for(j=0;j<6;j++){glEnableVertexAttribArray(j);glVertexAttribPointer(j,sizes[j],GL_FLOAT,GL_FALSE,72,(const void*)(uintptr_t)offsets[j]);}}
 glBindVertexArray(0);return glGetError()==GL_NO_ERROR;
}
static GLint loc(state*s,const char*n){return glGetUniformLocation(s->program,n);}
static void bind(GLuint p,const char*n,unsigned unit,GLenum target,GLuint t){glActiveTexture(GL_TEXTURE0+unit);glBindTexture(target,t);glUniform1i(glGetUniformLocation(p,n),unit);}
int oa_native_water_draw(oa_native_water*w,const float vp[16],const float eye[3],GLuint color,GLuint depth,const float inv[2],float time,const oa_native_water_environment*e){state*s=(state*)w->state;unsigned i,j;if(!s||!e||!e->ambient_cube||!color||!depth)return 0;if(!gpu(s)){oa_native_water_gpu_close(w);return 0;}glUseProgram(s->program);glUniformMatrix4fv(loc(s,"vp"),1,GL_FALSE,vp);glUniform3fv(loc(s,"eye"),1,eye);glUniform2fv(loc(s,"invDepth"),1,inv);glUniform1f(loc(s,"time"),time);glUniform3fv(loc(s,"sunDirection"),1,e->sun_direction);glUniform3fv(loc(s,"sunColor"),1,e->sun_color);glUniform3fv(loc(s,"shadowColor"),1,e->shadow_color);glUniform3fv(loc(s,"waterFog"),1,e->water_fog);bind(s->program,"sceneColor",5,GL_TEXTURE_2D,color);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);bind(s->program,"sceneDepth",6,GL_TEXTURE_2D,depth);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_COMPARE_MODE,GL_NONE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);bind(s->program,"ambientCube",8,GL_TEXTURE_CUBE_MAP,e->ambient_cube);
 glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(GL_FALSE);glEnable(GL_BLEND);glBlendEquation(GL_FUNC_ADD);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);glEnable(GL_CULL_FACE);glCullFace(GL_BACK);glFrontFace(GL_CCW);
 for(i=0;i<s->nm;i++){mesh*m=s->m+i;const char*names[5]={"baseMap","normalMap","foamMap","detailMap","refractionMap"};for(j=0;j<5;j++)bind(s->program,names[j],j,GL_TEXTURE_2D,findtex(s,m->texid[j])->gpu);bind(s->program,"probeCube",7,GL_TEXTURE_CUBE_MAP,findtex(s,m->probe)->gpu);glUniform4fv(loc(s,"m[0]"),6,m->m);glUniform4fv(loc(s,"lightData[0]"),8,m->lights);glUniform4fv(loc(s,"globalTint"),1,m->tint);glUniform4fv(loc(s,"lumFactors"),1,m->lum);glUniform3fv(loc(s,"lumTint"),1,m->lumtint);glUniform1i(loc(s,"pointLights"),m->points);glBindVertexArray(m->vao);glDrawElements(GL_TRIANGLES,m->ni,GL_UNSIGNED_INT,0);}
 glBindVertexArray(0);glActiveTexture(GL_TEXTURE0);glDisable(GL_BLEND);glDepthMask(GL_TRUE);return glGetError()==GL_NO_ERROR;
}
int oa_native_water_contains(const oa_native_water*w,unsigned material,const float p[3],float tolerance){state*s=(state*)w->state;unsigned i,j;if(!s)return 0;for(i=0;i<s->nm;i++){mesh*m=s->m+i;int yes=1;if(m->material!=material)continue;for(j=0;j<3;j++)if(p[j]<m->bounds[j]-tolerance||p[j]>m->bounds[j+3]+tolerance)yes=0;if(yes)return 1;}return 0;}
